package storage

import (
	"context"
	"fmt"
	"sort"
	"strings"
)

// Dashboard queries return bounded projections, never entire payloads in the
// timeline. Detail stays in InspectContext; none of these readers writes state.
const DashboardWindow = 1000
const DashboardPageSize = 50

type EventSummary struct {
	ID              string `json:"id"`
	Source          string `json:"source"`
	Type            string `json:"type"`
	Subject         string `json:"subject"`
	IngestedAt      string `json:"ingested_at"`
	EventTime       string `json:"event_time"`
	Message         string `json:"message"`
	DecisionStatus  string `json:"decision_status"`
	Model           string `json:"model"`
	LatencyMs       *int64 `json:"latency_ms"`
	Outcome         string `json:"outcome"`
	ExecutionStatus string `json:"execution_status"`
	Labeled         bool   `json:"labeled"`
}

type EventPage struct {
	Events []EventSummary `json:"events"`
	More   bool           `json:"more"`
}

// Search uses bound values and instr rather than LIKE, so user text is literal.
// Views use a fixed allowlist; no client-supplied SQL fragments reach the query.
func (d *DB) DashboardEvents(ctx context.Context, query, view string, offset int) (EventPage, error) {
	out := EventPage{Events: []EventSummary{}}
	views := map[string]string{
		"all": "1", "unlabeled": "l.event_id IS NULL",
		"shadow": "x.status = 'shadow'", "ignore": "x.outcome = 'ignore'",
		"errors": "(d.status IN ('errored','invalid') OR x.status = 'error')",
	}
	where, ok := views[view]
	if !ok || offset < 0 || offset > 100000 || len(query) > 200 {
		return out, fmt.Errorf("invalid event query")
	}
	rows, err := d.QueryContext(ctx, `SELECT e.id,e.source,e.type,e.subject,e.ingest_time,e.event_time,
		COALESCE(json_extract(e.data,'$.message'),''),
		COALESCE(d.status,''),COALESCE(d.model,''),d.latency_ms,
		COALESCE(x.outcome,''),COALESCE(x.status,''),l.event_id IS NOT NULL
		FROM events e
		LEFT JOIN decisions d ON d.id=(SELECT id FROM decisions WHERE event_id=e.id ORDER BY created_at DESC,id DESC LIMIT 1)
		LEFT JOIN executions x ON x.id=(SELECT id FROM executions WHERE event_id=e.id ORDER BY created_at DESC,id DESC LIMIT 1)
		LEFT JOIN event_labels l ON l.event_id=e.id
		WHERE `+where+` AND (?='' OR instr(lower(e.subject || ' ' || e.source || ' ' || e.type || ' ' || e.id || ' ' || COALESCE(e.data,'')),lower(?))>0)
		ORDER BY e.ingest_time DESC,e.id DESC LIMIT ? OFFSET ?`, query, query, DashboardPageSize+1, offset)
	if err != nil {
		return out, fmt.Errorf("dashboard events: %w", err)
	}
	defer rows.Close()
	for rows.Next() {
		var e EventSummary
		if err := rows.Scan(&e.ID, &e.Source, &e.Type, &e.Subject, &e.IngestedAt, &e.EventTime, &e.Message, &e.DecisionStatus, &e.Model, &e.LatencyMs, &e.Outcome, &e.ExecutionStatus, &e.Labeled); err != nil {
			return out, fmt.Errorf("scan dashboard event: %w", err)
		}
		out.Events = append(out.Events, e)
	}
	if err := rows.Err(); err != nil {
		return out, fmt.Errorf("read dashboard events: %w", err)
	}
	out.More = len(out.Events) > DashboardPageSize
	if out.More {
		out.Events = out.Events[:DashboardPageSize]
	}
	return out, nil
}

type ModelTiming struct {
	Interpreter string `json:"interpreter"`
	Model       string `json:"model"`
	Count       int    `json:"count"`
	Successes   int    `json:"successes"`
	Errors      int    `json:"errors"`
	Timeouts    int    `json:"timeouts"`
	MedianMs    *int64 `json:"median_ms"`
	P95Ms       *int64 `json:"p95_ms"`
	LastAt      string `json:"last_at"`
	LastStatus  string `json:"last_status"`
	LastMs      int64  `json:"last_ms"`
	LastSuccess string `json:"last_success"`
	LastError   string `json:"last_error"`
}

type Repeat struct {
	Source  string `json:"source"`
	Subject string `json:"subject"`
	Message string `json:"message"`
	Count   int    `json:"count"`
}

type DashboardSummary struct {
	Events    int           `json:"events"`
	Unlabeled int           `json:"unlabeled"`
	Shadow    int           `json:"shadow"`
	Ignored   int           `json:"ignored"`
	Pending   int           `json:"pending"`
	Window    int           `json:"window"`
	Models    []ModelTiming `json:"models"`
	Repeats   []Repeat      `json:"repeats"`
}

func (d *DB) DashboardSummary(ctx context.Context) (DashboardSummary, error) {
	s := DashboardSummary{Window: DashboardWindow, Models: []ModelTiming{}, Repeats: []Repeat{}}
	if err := d.QueryRowContext(ctx, `SELECT (SELECT count(*) FROM events),
		(SELECT count(*) FROM events e WHERE NOT EXISTS(SELECT 1 FROM event_labels l WHERE l.event_id=e.id)),
		(SELECT count(*) FROM executions WHERE status='shadow'),
		(SELECT count(*) FROM executions WHERE outcome='ignore'),
		(SELECT count(*) FROM executions WHERE status='pending')`).Scan(&s.Events, &s.Unlabeled, &s.Shadow, &s.Ignored, &s.Pending); err != nil {
		return s, fmt.Errorf("dashboard counts: %w", err)
	}
	rows, err := d.QueryContext(ctx, `SELECT interpreter,model,status,latency_ms,created_at,COALESCE(error,'') FROM decisions ORDER BY created_at DESC,id DESC LIMIT ?`, DashboardWindow)
	if err != nil {
		return s, fmt.Errorf("dashboard timings: %w", err)
	}
	// Release the sole SQLite connection before querying repetitions. Bounded
	// samples keep percentile memory fixed even after years of collection.
	indices := map[[2]string]int{}
	timings := map[int][]int64{}
	for rows.Next() {
		var interpreter, model, status, at, detail string
		var ms int64
		if err = rows.Scan(&interpreter, &model, &status, &ms, &at, &detail); err != nil {
			break
		}
		key := [2]string{interpreter, model}
		i, exists := indices[key]
		if !exists {
			i = len(s.Models)
			indices[key] = i
			s.Models = append(s.Models, ModelTiming{Interpreter: interpreter, Model: model, LastAt: at, LastStatus: status, LastMs: ms})
		}
		m := &s.Models[i]
		m.Count++
		if status == "ok" {
			m.Successes++
			timings[i] = append(timings[i], ms)
			if m.LastSuccess == "" {
				m.LastSuccess = at
			}
		} else {
			m.Errors++
			if m.LastError == "" {
				m.LastError = at
			}
			// Historical decisions predate structured failure kinds. Count only
			// recorded timeout/deadline errors, never infer failure from latency.
			if IsTimeout(detail) {
				m.Timeouts++
			}
		}
	}
	if err == nil {
		err = rows.Err()
	}
	rows.Close()
	if err != nil {
		return s, fmt.Errorf("read dashboard timings: %w", err)
	}
	for i := range s.Models {
		values := timings[i]
		sort.Slice(values, func(a, b int) bool { return values[a] < values[b] })
		if len(values) > 0 {
			// Nearest-rank percentiles are defined even for a single observation.
			median, p95 := values[(len(values)-1)/2], values[(95*len(values)+99)/100-1]
			s.Models[i].MedianMs, s.Models[i].P95Ms = &median, &p95
		}
	}
	rows, err = d.QueryContext(ctx, `SELECT source,subject,message,count(*) n FROM
		(SELECT source,type,subject,COALESCE(json_extract(data,'$.message'),'') message FROM events ORDER BY ingest_time DESC,id DESC LIMIT ?)
		WHERE message!='' GROUP BY source,type,subject,message HAVING count(*)>1 ORDER BY n DESC,source,subject LIMIT 10`, DashboardWindow)
	if err != nil {
		return s, fmt.Errorf("dashboard repeats: %w", err)
	}
	defer rows.Close()
	for rows.Next() {
		var r Repeat
		if err := rows.Scan(&r.Source, &r.Subject, &r.Message, &r.Count); err != nil {
			return s, fmt.Errorf("scan repeat: %w", err)
		}
		s.Repeats = append(s.Repeats, r)
	}
	if err := rows.Err(); err != nil {
		return s, fmt.Errorf("read repeats: %w", err)
	}
	return s, nil
}

func IsTimeout(detail string) bool {
	detail = strings.ToLower(detail)
	return strings.Contains(detail, "timeout") || strings.Contains(detail, "deadline exceeded")
}

package storage

import (
	"context"
	"database/sql"
	"errors"
	"fmt"
	"testing"
	"time"

	"github.com/heath0xff/mrmr/internal/event"
)

func dashboardEvent(t *testing.T, db *DB, n int) string {
	t.Helper()
	id := fmt.Sprintf("evt_%04d", n)
	_, err := db.InsertEvent(event.Event{ID: id, Type: "service.warning", Source: "journal", Subject: "test.service", Timestamp: time.Now().UTC(), Data: map[string]any{"message": "Repeated warning"}, Metadata: map[string]any{"source_event_id": id}})
	if err != nil {
		t.Fatal(err)
	}
	// Fixed ingestion order makes pagination and the percentile window stable.
	if _, err := db.Exec(`UPDATE events SET ingest_time=? WHERE id=?`, time.Unix(int64(n), 0).UTC().Format(time.RFC3339Nano), id); err != nil {
		t.Fatal(err)
	}
	return id
}

func TestDashboardSummaryAndViews(t *testing.T) {
	db := openTestDB(t)
	ctx := context.Background()
	for i, status := range []string{"ok", "ok", "errored", "invalid"} {
		id := dashboardEvent(t, db, i)
		dec := event.Decision{ID: fmt.Sprintf("dec_%d", i), EventID: id, Interpreter: "judge", Model: "d1", Status: status, LatencyMs: []int64{10, 30, 90000, 0}[i]}
		if status == "errored" {
			dec.Error = "model call: i/o timeout"
		}
		if err := db.InsertDecision(dec); err != nil {
			t.Fatal(err)
		}
		if err := db.InsertExecution("exe_"+id, id, dec.ID, "notify", "discord", "shadow", ""); err != nil {
			t.Fatal(err)
		}
	}
	if _, err := db.LabelEvent("evt_0000", "routine", false, "ignore"); err != nil {
		t.Fatal(err)
	}
	// A second model with no successes must not invent a zero-ms percentile.
	id := dashboardEvent(t, db, 4)
	if err := db.InsertDecision(event.Decision{ID: "dec_other", EventID: id, Interpreter: "other", Model: "other", Status: "errored", Error: "connection refused", LatencyMs: 1}); err != nil {
		t.Fatal(err)
	}
	s, err := db.DashboardSummary(ctx)
	if err != nil {
		t.Fatal(err)
	}
	if s.Events != 5 || s.Unlabeled != 4 || s.Shadow != 4 || len(s.Repeats) != 1 || s.Repeats[0].Count != 5 {
		t.Fatalf("summary: %+v", s)
	}
	for _, m := range s.Models {
		if m.Model == "d1" {
			if m.Count != 4 || m.Successes != 2 || m.Errors != 2 || m.Timeouts != 1 || *m.MedianMs != 10 || *m.P95Ms != 30 || m.LastSuccess == "" || m.LastError == "" {
				t.Fatalf("timing: %+v", m)
			}
		} else if m.MedianMs != nil || m.P95Ms != nil || m.Timeouts != 0 {
			t.Fatalf("no success: %+v", m)
		}
	}
	for view, want := range map[string]int{"all": 5, "unlabeled": 4, "shadow": 4, "ignore": 0, "errors": 3} {
		p, err := db.DashboardEvents(ctx, "", view, 0)
		if err != nil || len(p.Events) != want {
			t.Fatalf("view %s: %+v, %v", view, p, err)
		}
	}
	for query, want := range map[string]int{"TEST.SERVICE": 5, "Repeated": 5, "%' OR 1=1 --": 0} {
		p, err := db.DashboardEvents(ctx, query, "all", 0)
		if err != nil || len(p.Events) != want {
			t.Fatalf("query %q: %+v, %v", query, p, err)
		}
	}
}

func TestDashboardPaginationEmptyAndCancellation(t *testing.T) {
	db := openTestDB(t)
	ctx := context.Background()
	s, err := db.DashboardSummary(ctx)
	if err != nil || s.Events != 0 || len(s.Models) != 0 || s.Models == nil {
		t.Fatalf("empty summary: %+v %v", s, err)
	}
	for i := 0; i < 52; i++ {
		dashboardEvent(t, db, i)
	}
	p, err := db.DashboardEvents(ctx, "", "all", 0)
	if err != nil || len(p.Events) != 50 || !p.More || p.Events[0].ID != "evt_0051" || p.Events[0].LatencyMs != nil {
		t.Fatalf("first page: %+v %v", p, err)
	}
	p, err = db.DashboardEvents(ctx, "", "all", 50)
	if err != nil || len(p.Events) != 2 || p.More || p.Events[0].ID != "evt_0001" {
		t.Fatalf("second page: %+v %v", p, err)
	}
	if _, err = db.DashboardEvents(ctx, "", "bad", 0); err == nil {
		t.Fatal("invalid view accepted")
	}
	if _, err = db.InspectContext(ctx, "missing"); !errors.Is(err, sql.ErrNoRows) {
		t.Fatalf("missing: %v", err)
	}
	ctx, cancel := context.WithCancel(ctx)
	cancel()
	if _, err = db.DashboardSummary(ctx); !errors.Is(err, context.Canceled) {
		t.Fatalf("summary cancellation: %v", err)
	}
	if _, err = db.DashboardEvents(ctx, "", "all", 0); !errors.Is(err, context.Canceled) {
		t.Fatalf("events cancellation: %v", err)
	}
	if _, err = db.InspectContext(ctx, "evt_0000"); !errors.Is(err, context.Canceled) {
		t.Fatalf("detail cancellation: %v", err)
	}
}

func TestDashboardWindowAndIndexMigration(t *testing.T) {
	db := openTestDB(t)
	id := dashboardEvent(t, db, 0)
	// More than one decision per event is supported by storage. Use it to pin
	// the bound without generating a thousand unrelated event payloads.
	for i := 0; i <= DashboardWindow; i++ {
		at := time.Unix(int64(i), 0).UTC().Format(time.RFC3339Nano)
		if _, err := db.Exec(`INSERT INTO decisions(id,event_id,interpreter,model,status,latency_ms,created_at) VALUES(?,?,?,?,?,?,?)`, fmt.Sprint(i), id, "judge", "d1", "ok", i, at); err != nil {
			t.Fatal(err)
		}
	}
	s, err := db.DashboardSummary(context.Background())
	if err != nil || len(s.Models) != 1 || s.Models[0].Count != DashboardWindow || *s.Models[0].MedianMs != 500 || *s.Models[0].P95Ms != 950 {
		t.Fatalf("window: %+v %v", s, err)
	}
	// Force the second index creation to fail. The first must roll back, and
	// an existing event must survive the failed upgrade.
	if _, err := db.Exec(`DROP INDEX idx_events_ingest; DELETE FROM schema_migrations WHERE version>=8`); err != nil {
		t.Fatal(err)
	}
	if err := db.migrate(); err == nil {
		t.Fatal("conflicting migration should fail")
	}
	var n int
	if err := db.QueryRow(`SELECT count(*) FROM sqlite_master WHERE name='idx_events_ingest'`).Scan(&n); err != nil || n != 0 {
		t.Fatalf("partial migration: %d %v", n, err)
	}
	if _, err := db.Inspect(id); err != nil {
		t.Fatal(err)
	}
}

