			}
			if len(b) > 4<<20 {
				http.Error(w, "Record is too large for the dashboard. Use mrmr inspect locally.", http.StatusRequestEntityTooLarge)
				return
			}
			var doc any
			dec := json.NewDecoder(bytes.NewReader(b))
			dec.UseNumber()
			if err := dec.Decode(&doc); err != nil {
