package main

import (
 "context"
 "crypto/sha256"
 "crypto/subtle"
 "encoding/hex"
 "encoding/json"
 "errors"
 "fmt"
 "io"
 "net"
 "net/http"
 "net/url"
 "os"
 "os/signal"
 "path/filepath"
 "strings"
 "sync"
 "sync/atomic"
 "syscall"
 "time"

 "github.com/heath0xff/mrmr/internal/config"
 "github.com/heath0xff/mrmr/internal/dashboard"
 "github.com/heath0xff/mrmr/internal/model"
 "github.com/heath0xff/mrmr/internal/runtime"
 "github.com/heath0xff/mrmr/internal/storage"
)

// A snapshot owns one immutable configuration. HTTP requests retain their
// snapshot until completion; activation never edits a runtime in place.
type managedSnapshot struct {
 cfg *config.Config
 rt *runtime.Runtime
 view http.Handler
 ingress http.Handler
 yaml string
 revision string
}

type manager struct {
 ctx context.Context
 db *storage.DB
 path string
 bootstrap *config.Config
 current atomic.Pointer[managedSnapshot]
 blocked atomic.Bool
 // Only one operator mutation or activation may proceed at a time. Reads
 // stay available while a source drains or a model evaluation is running.
 op sync.Mutex
 token [32]byte
 host string
 stopSources chan struct{}
 sources sync.WaitGroup
 evalMu sync.Mutex
 evalCancel context.CancelFunc
 evalWG sync.WaitGroup
}

func revision(text string) string { sum:=sha256.Sum256([]byte(text)); return hex.EncodeToString(sum[:]) }

func runManaged(path, addr, host, tokenEnv string, setup bool, setupDB string) error {
 ip, port, err := net.SplitHostPort(addr)
 if err != nil || net.ParseIP(ip)==nil || !net.ParseIP(ip).IsLoopback() || port=="0" { return fmt.Errorf("control-addr must be a literal loopback address with a nonzero port") }
 if host!="" { if strings.ContainsAny(host,"/:@ \\?#") || strings.ToLower(host)!=host { return fmt.Errorf("control-host must be an exact lowercase hostname") } }
 token := os.Getenv(tokenEnv)
 if len(token)<32 { return fmt.Errorf("management requires a random token of at least 32 bytes in its configured environment variable") }
 b, err := os.ReadFile(path)
 var cfg *config.Config
 if errors.Is(err,os.ErrNotExist) && setup {
  cfg=&config.Config{Server:config.Server{Addr:"127.0.0.1:4242"}, DB:config.DB{Path:setupDB}}
 } else if err!=nil { return fmt.Errorf("read startup configuration: %w",err) } else {
  cfg,err=config.Parse(b); if err!=nil { return err }
 }
 // Config versions contain references, never secret values. Refuse unsafe
 // legacy config before exposing an editor or making a history copy.
 if len(b)>0 { if err:=managementSafe(b); err!=nil { return err } }
 if _,err:=os.Lstat(path); err==nil { info,_:=os.Lstat(path); if info.Mode()&os.ModeSymlink!=0 { return fmt.Errorf("managed config must not be a symlink") } }
 db,err:=storage.Open(cfg.DB.Path); if err!=nil { return err }; defer db.Close()
 ctx,cancel:=signal.NotifyContext(context.Background(),os.Interrupt,syscall.SIGTERM); defer cancel()
 m:=&manager{ctx:ctx, db:db,path:path,bootstrap:cfg,host:host,token:sha256.Sum256([]byte(token))}
 var blocked string
 err=db.QueryRow(`SELECT value FROM control_settings WHERE name='shadow'`).Scan(&blocked)
 m.blocked.Store(blocked=="true")
 // Crashed evaluations are evidence of interrupted work, never jobs to replay.
 if _,err=db.Exec(`UPDATE control_evaluations SET status='interrupted' WHERE status='running'`); err!=nil { return err }
 if len(b)>0 {
  snap:=m.snapshot(cfg,string(b))
  jobs,err:=m.prepare(cfg); if err!=nil { return err }
  if _,err=db.Exec(`INSERT OR IGNORE INTO control_revisions(id,yaml,created_at,status,base) VALUES(?,?,?,'active','')`,snap.revision,snap.yaml,time.Now().UTC().Format(time.RFC3339Nano));err!=nil{return err}
  m.current.Store(snap); m.startSources(jobs,snap.rt)
 }
 // All listeners are bound before serving. A failed bind cannot leave an
 // unattended management endpoint or source goroutine behind.
 defer func(){cancel();m.sources.Wait();m.cancelEvaluation();m.evalWG.Wait()}()
 controlListener,err:=net.Listen("tcp",addr);if err!=nil{return err};defer controlListener.Close()
 ingressListener,err:=net.Listen("tcp",cfg.Server.Addr);if err!=nil{return err};defer ingressListener.Close()
 view:=http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){s:=m.current.Load();if s==nil{http.Error(w,"Setup is not complete.",503);return};s.view.ServeHTTP(w,r)})
 mux:=http.NewServeMux()
 mux.HandleFunc("POST /api/events",func(w http.ResponseWriter,r *http.Request){s:=m.current.Load();if s==nil{http.Error(w,"Collection is disabled until setup completes.",503);return};s.ingress.ServeHTTP(w,r)})
 mux.Handle("/dashboard/",view);mux.Handle("/dashboard",view);mux.Handle("GET /{$}",view)
 servers:=[]*http.Server{{Handler:m,ReadHeaderTimeout:5*time.Second,IdleTimeout:time.Minute},{Handler:mux,ReadHeaderTimeout:5*time.Second,IdleTimeout:time.Minute}}
 listeners:=[]net.Listener{controlListener,ingressListener}
 if cfg.Server.DashboardAddr!="" { l,err:=net.Listen("tcp",cfg.Server.DashboardAddr);if err!=nil{return err};defer l.Close();listeners=append(listeners,l);servers=append(servers,&http.Server{Handler:view,ReadHeaderTimeout:5*time.Second,IdleTimeout:time.Minute}) }
 errs:=make(chan error,len(servers));var serving sync.WaitGroup
 for i,s:=range servers { serving.Add(1);go func(){defer serving.Done();errs<-s.Serve(listeners[i])}() }
 defer func(){for _,s:=range servers{s.Close()};serving.Wait()}()
 fmt.Printf("mrmr management listening on %s (private operator access required)\n",addr)
 select {case <-ctx.Done():case err=<-errs:}
 cancel()
 deadline,done:=context.WithTimeout(context.Background(),15*time.Second);defer done()
 for _,s:=range servers{s.Shutdown(deadline)}
 if errors.Is(err,http.ErrServerClosed){return nil};return err
}

func (m *manager) snapshot(cfg *config.Config, text string)*managedSnapshot {
 rt:=&runtime.Runtime{DB:m.db,Client:&model.Client{},ModelCfg:cfg.Models[cfg.Interpret.Model],ModelKey:cfg.Interpret.Model,Prompt:cfg.Interpret.Prompt,Schema:cfg.Interpret.Schema,Questions:cfg.Interpret.Questions,Policy:cfg.Policy,Filters:cfg.Filter,Agents:cfg.Agents,Models:cfg.Models,InterpretByType:cfg.InterpretByType,EffectsBlocked:m.blocked.Load}
 return &managedSnapshot{cfg:cfg,rt:rt,view:dashboard.New(rt,cfg),ingress:eventsHandler(rt),yaml:text,revision:revision(text)}
}

func (m *manager) ServeHTTP(w http.ResponseWriter,r *http.Request){
 w.Header().Set("Cache-Control","no-store");w.Header().Set("X-Content-Type-Options","nosniff");w.Header().Set("Referrer-Policy","no-referrer")
 w.Header().Set("Content-Security-Policy","default-src 'none'; script-src 'self'; style-src 'self'; connect-src 'self'; base-uri 'none'; frame-ancestors 'none'; form-action 'none'")
 peer,_,err:=net.SplitHostPort(r.RemoteAddr);host:=r.Host;if h,_,e:=net.SplitHostPort(host);e==nil{host=h}
 local:=net.ParseIP(peer)!=nil&&net.ParseIP(peer).IsLoopback()
 if err!=nil||!local||(host!="localhost"&&host!="127.0.0.1"&&host!="::1"&&host!=m.host)||r.Header.Get("Sec-Fetch-Site")=="cross-site" {http.Error(w,"Private management access required.",403);return}
 if origin:=r.Header.Get("Origin");origin!="" {u,e:=url.Parse(origin);if e!=nil||u.Host!=r.Host||(u.Scheme!="http"&&u.Scheme!="https"){http.Error(w,"Origin rejected.",403);return}}
 if r.Method=="GET"&&(r.URL.Path=="/manage/"||r.URL.Path=="/manage/manage.js"||r.URL.Path=="/manage/manage.css") {dashboard.ManagementAsset(w,r);return}
 if r.Method=="GET"&&r.URL.Path=="/"{http.Redirect(w,r,"/manage/",307);return}
 // The browser retains the token only in memory, not cookies, URLs, storage,
 // or service logs. An explicit header prevents ambient browser authority.
 auth:=strings.TrimPrefix(r.Header.Get("Authorization"),"Bearer ")
 hash:=sha256.Sum256([]byte(auth))
 if !strings.HasPrefix(r.Header.Get("Authorization"),"Bearer ")||subtle.ConstantTimeCompare(hash[:],m.token[:])!=1 {http.Error(w,"Operator token required.",401);return}
 if r.Method!="GET"&&r.Method!="POST"{http.Error(w,"Method not allowed.",405);return}
 if r.Method=="POST"&&(r.Header.Get("X-Mrmr-Control")!="1"||!strings.HasPrefix(r.Header.Get("Content-Type"),"application/json")){http.Error(w,"Explicit JSON control request required.",403);return}
 // The management origin can read existing evidence, but never receives the
 // ingestion mux. Even authenticated callers cannot submit arbitrary events.
 if strings.HasPrefix(r.URL.Path,"/dashboard/") {s:=m.current.Load();if s==nil{http.Error(w,"Setup is not complete.",503);return}; clone:=r.Clone(r.Context());clone.Host="localhost";clone.Header=r.Header.Clone();clone.Header.Del("Origin");s.view.ServeHTTP(w,clone);return}
 if r.Method=="POST" {if !m.op.TryLock(){http.Error(w,"Another change is in progress. Retry shortly.",409);return};defer m.op.Unlock()}
 if err:=m.route(w,r);err!=nil{http.Error(w,err.Error(),http.StatusBadRequest)}
}

func decodeControl(w http.ResponseWriter,r *http.Request,v any)error{
 r.Body=http.MaxBytesReader(w,r.Body,256<<10)
 d:=json.NewDecoder(r.Body);d.DisallowUnknownFields()
 if err:=d.Decode(v);err!=nil{return fmt.Errorf("Invalid or oversized JSON request.")}
 if err:=d.Decode(new(any));err!=io.EOF{return fmt.Errorf("Expected one JSON object.")};return nil
}
func controlJSON(w http.ResponseWriter,v any)error{w.Header().Set("Content-Type","application/json");return json.NewEncoder(w).Encode(v)}
func (m *manager)audit(operation,target,result string)error{_,err:=m.db.Exec(`INSERT INTO control_audit(at,actor,operation,target,result) VALUES(?,'operator',?,?,?)`,time.Now().UTC().Format(time.RFC3339Nano),operation,target,result);return err}

// Atomic replacement prevents a crash from leaving truncated startup YAML.
// A private temp file is synced before rename; the containing directory is
// synced too. Callers compare the disk revision immediately before this call.
func replaceConfig(path,text string)error{
 f,err:=os.CreateTemp(filepath.Dir(path),".mrmr-config-*");if err!=nil{return err};defer os.Remove(f.Name())
 if _,err=f.WriteString(text);err==nil{err=f.Sync()};closeErr:=f.Close();if err==nil{err=closeErr};if err!=nil{return err}
 if err=os.Rename(f.Name(),path);err!=nil{return err}
 dir,err:=os.Open(filepath.Dir(path));if err!=nil{return err};defer dir.Close();return dir.Sync()
}

package main

import (
 "context"
 "database/sql"
 "encoding/json"
 "fmt"
 "net/http"
 "net/url"
 "os"
 "reflect"
 "regexp"
 "strings"
 "time"

 "gopkg.in/yaml.v3"
 "github.com/heath0xff/mrmr/internal/config"
 "github.com/heath0xff/mrmr/internal/runtime"
 "github.com/heath0xff/mrmr/internal/source"
)

type sourceJob func(context.Context,<-chan struct{},*runtime.Runtime)
type configDraft struct {YAML string `json:"yaml"`;Revision string `json:"revision"`;Base string `json:"base"`}
type configRequest struct {YAML string `json:"yaml"`;Expected string `json:"expected"`;Base string `json:"base"`;Confirm bool `json:"confirm"`}

func (m *manager) prepare(c *config.Config)([]sourceJob,error){
 var jobs []sourceJob
 for _,s:=range c.Sources {
  if s.Paused{continue}
  switch s.Type {
  case "http-poller":p,err:=source.NewHTTPPoller(s);if err!=nil{return nil,fmt.Errorf("HTTP source readiness failed; check URL mapping and credential references.")};jobs=append(jobs,p.RunUntil)
  case "systemd-journal":p,err:=source.NewJournal(m.ctx,s,m.db);if err!=nil{return nil,fmt.Errorf("Journal readiness failed; check platform, access, and saved cursor.")};jobs=append(jobs,p.RunUntil)
  default:return nil,fmt.Errorf("Unsupported source type.")
  }
 }
 return jobs,nil
}
func (m *manager)startSources(jobs []sourceJob,rt *runtime.Runtime){
 m.stopSources=make(chan struct{})
 stop:=m.stopSources
 for _,job:=range jobs{m.sources.Add(1);go func(){defer m.sources.Done();job(m.ctx,stop,rt)}()}
}
func (m *manager)activeRevision()string{if s:=m.current.Load();s!=nil{return s.revision};return revision("")}

// Management refuses literal credentials instead of trying to round-trip a
// redacted file. Endpoint locations are configuration; secret values belong
// in environment variables provisioned outside the browser.
var inlineSecret=REDACTED
func managementSafe(b []byte)error{
 if len(b)>256<<10{return fmt.Errorf("Configuration exceeds 256 KiB.")}
 var doc any
 if err:=yaml.Unmarshal(b,&doc);err!=nil{return fmt.Errorf("Invalid YAML; check indentation, duplicate keys, and field types.")}
 var walk func(any)error
 walk=func(v any)error{switch v:=v.(type){
 case map[string]any:for k,x:=range v{l:=strings.ToLower(k);if l=="token"||l=="password"||l=="secret"||l=="api_key"||l=="authorization"||l=="webhook_url"{return fmt.Errorf("Inline credentials are not allowed; use environment references.")};if err:=walk(x);err!=nil{return err}}
 case []any:for _,x:=range v{if err:=walk(x);err!=nil{return err}}
 case string:
  if inlineSecret.MatchString(v){return fmt.Errorf("Possible inline credential detected; use environment references.")}
  if strings.HasPrefix(v,"http://")||strings.HasPrefix(v,"https://"){u,e:=url.Parse(v);if e==nil&&(u.User!=nil||strings.Contains(u.Path,"/api/webhooks/")){return fmt.Errorf("Credential-bearing URLs are not allowed in managed configuration.")}}
 };return nil}
 if err:=walk(doc);err!=nil{return err}
 // Detect values of configured secret references, including accidental copies
 // inside prompts or comments. Never echo the matched value in an error.
 c,err:=config.Parse(b);if err==nil{names:=[]string{};for _,v:=range c.Models{names=append(names,v.APIKeyEnv)};for _,v:=range c.Sources{names=append(names,v.BearerTokenEnv)};for _,v:=range c.Policy.Rules{if v.Then.Notify!=nil{names=append(names,v.Then.Notify.WebhookEnv)}};if c.Policy.Default.Notify!=nil{names=append(names,c.Policy.Default.Notify.WebhookEnv)};for _,n:=range names{if n!=""{if value:=os.Getenv(n);value!=""&&strings.Contains(string(b),value){return fmt.Errorf("Configuration contains a credential value; only its environment reference may be stored.")}}}}
 return nil
}
func managedParse(text string)(*config.Config,error){
 if err:=managementSafe([]byte(text));err!=nil{return nil,err}
 c,err:=config.Parse([]byte(text));if err!=nil{return nil,fmt.Errorf("Configuration is invalid. Check required fields, model roles, source mappings, and policy rules against the supported schema.")};return c,nil
}

func (m *manager)route(w http.ResponseWriter,r *http.Request)error{
 switch {
 case r.Method=="GET"&&r.URL.Path=="/manage/api/state":
  var draft configDraft
  err:=m.db.QueryRow(`SELECT yaml,revision,base FROM control_draft WHERE singleton=1`).Scan(&draft.YAML,&draft.Revision,&draft.Base);if err!=nil&&err!=sql.ErrNoRows{return fmt.Errorf("Cannot read draft.")}
  active:="";if s:=m.current.Load();s!=nil{active=s.yaml}
  var history []map[string]any
  rows,err:=m.db.Query(`SELECT id,created_at,status,base FROM control_revisions ORDER BY created_at DESC LIMIT 30`);if err!=nil{return fmt.Errorf("Cannot read configuration history.")}
  for rows.Next(){var id,at,status,base string;if err:=rows.Scan(&id,&at,&status,&base);err!=nil{rows.Close();return fmt.Errorf("Cannot read revision.")};history=append(history,map[string]any{"id":id,"at":at,"status":status,"base":base})};err=rows.Err();rows.Close();if err!=nil{return fmt.Errorf("Cannot read revisions.")}
  var doc any;if active!=""{yaml.Unmarshal([]byte(active),&doc)}
  return controlJSON(w,map[string]any{"active":active,"revision":m.activeRevision(),"draft":draft,"history":history,"document":doc,"setup":m.current.Load()==nil,"shadow_override":m.blocked.Load(),"bootstrap":m.bootstrap})
 case r.Method=="GET"&&r.URL.Path=="/manage/api/revision":
  var text string;if err:=m.db.QueryRow(`SELECT yaml FROM control_revisions WHERE id=?`,r.URL.Query().Get("id")).Scan(&text);err!=nil{return fmt.Errorf("Revision not found.")};return controlJSON(w,map[string]string{"yaml":text})
 case r.Method=="POST"&&r.URL.Path=="/manage/api/compose":
  var req struct{Document map[string]any `json:"document"`};if err:=decodeControl(w,r,&req);err!=nil{return err};b,err:=yaml.Marshal(req.Document);if err!=nil{return fmt.Errorf("Cannot encode configuration.")};if err:=managementSafe(b);err!=nil{return err};return controlJSON(w,map[string]string{"yaml":string(b)})
 case r.Method=="POST"&&(r.URL.Path=="/manage/api/validate"||r.URL.Path=="/manage/api/draft"||r.URL.Path=="/manage/api/activate"):
  var req configRequest;if err:=decodeControl(w,r,&req);err!=nil{return err}
  c,err:=managedParse(req.YAML);if err!=nil{return err}
  var doc any;yaml.Unmarshal([]byte(req.YAML),&doc)
  if r.URL.Path=="/manage/api/validate"{return controlJSON(w,map[string]any{"valid":true,"document":doc,"revision":revision(req.YAML),"notice":"Validation makes no model calls and does not prove source or model availability."})}
  if req.Base!=m.activeRevision(){http.Error(w,"Active configuration changed. Reload before saving.",409);return nil}
  if r.URL.Path=="/manage/api/draft"{
   tx,err:=m.db.Begin();if err!=nil{return fmt.Errorf("Cannot save draft.")};defer tx.Rollback()
   var prior string;err=tx.QueryRow(`SELECT revision FROM control_draft WHERE singleton=1`).Scan(&prior);if err!=nil&&err!=sql.ErrNoRows{return fmt.Errorf("Cannot read draft revision.")}
   if prior!=req.Expected{http.Error(w,"Draft changed in another session. Reload before saving.",409);return nil}
   id:=revision(req.YAML)
   if _,err=tx.Exec(`INSERT INTO control_draft VALUES(1,?,?,?) ON CONFLICT(singleton) DO UPDATE SET yaml=excluded.yaml,revision=excluded.revision,base=excluded.base`,req.YAML,id,req.Base);err!=nil{return fmt.Errorf("Cannot save draft.")}
   if _,err=tx.Exec(`INSERT INTO control_audit(at,actor,operation,target,result) VALUES(?,'operator','save-draft',?,'saved')`,time.Now().UTC().Format(time.RFC3339Nano),id);err!=nil{return fmt.Errorf("Cannot audit draft.")}
   if err=tx.Commit();err!=nil{return fmt.Errorf("Cannot commit draft.")};return controlJSON(w,configDraft{req.YAML,id,req.Base})
  }
  if !req.Confirm{return fmt.Errorf("Confirm collection scope, data destination, and the displayed configuration diff before activation.")}
  var saved configDraft;if err=m.db.QueryRow(`SELECT yaml,revision,base FROM control_draft WHERE singleton=1`).Scan(&saved.YAML,&saved.Revision,&saved.Base);err!=nil||saved.Revision!=req.Expected||saved.YAML!=req.YAML||saved.Base!=req.Base{http.Error(w,"Save this exact draft against the active revision before applying it.",409);return nil}
  if err=m.activate(r.Context(),c,req.YAML,req.Base);err!=nil{return err};return controlJSON(w,map[string]string{"revision":m.activeRevision()})
 case r.Method=="POST"&&r.URL.Path=="/manage/api/shadow":
  var req struct{Confirm bool `json:"confirm"`};if err:=decodeControl(w,r,&req);err!=nil{return err};if !req.Confirm{return fmt.Errorf("Confirm the safety change.")}
  // Close the gate before writing: a storage failure must not reopen effects.
  m.blocked.Store(true)
  tx,err:=m.db.Begin();if err!=nil{return fmt.Errorf("Effects blocked in memory, but persistence failed. Retry before restarting.")};defer tx.Rollback()
  if _,err=tx.Exec(`INSERT INTO control_settings VALUES('shadow','true') ON CONFLICT(name) DO UPDATE SET value='true'`);err!=nil{return fmt.Errorf("Cannot persist safety gate; retry before restarting.")}
  if _,err=tx.Exec(`INSERT INTO control_audit(at,actor,operation,target,result) VALUES(?,'operator','return-to-shadow','effects','blocked')`,time.Now().UTC().Format(time.RFC3339Nano));err!=nil{return fmt.Errorf("Cannot persist safety audit.")}
  if err=tx.Commit();err!=nil{return fmt.Errorf("Cannot commit safety gate; retry before restarting.")};return controlJSON(w,map[string]bool{"shadow_override":true})
 case r.Method=="GET"&&r.URL.Path=="/manage/api/audit":
  rows,err:=m.db.Query(`SELECT at,actor,operation,target,result FROM control_audit ORDER BY id DESC LIMIT 100`);if err!=nil{return fmt.Errorf("Cannot read audit.")};defer rows.Close();out:=[]map[string]string{};for rows.Next(){var at,actor,op,target,result string;if rows.Scan(&at,&actor,&op,&target,&result)!=nil{return fmt.Errorf("Cannot decode audit.")};out=append(out,map[string]string{"at":at,"actor":actor,"operation":op,"target":target,"result":result})};if rows.Err()!=nil{return fmt.Errorf("Cannot read audit.")};return controlJSON(w,out)
 default:return m.reviewRoute(w,r)
 }
}

func (m *manager)activate(ctx context.Context,c *config.Config,text,base string)error{
 // Network binding and database relocation require a supervised process
 // restart. Refuse them here rather than claiming a partial activation.
 if c.Server!=m.bootstrap.Server||c.DB!=m.bootstrap.DB{return fmt.Errorf("Listener and database changes require a process restart; keep the current server and db settings.")}
 for _,r:=range c.Policy.Rules{if r.Then.Outcome()!="ignore"&&!r.Then.Shadow{return fmt.Errorf("Management activation requires shadow effects. Live promotion needs reviewed evaluation evidence.")}}
 if c.Policy.Default.Outcome()!="ignore"&&!c.Policy.Default.Shadow{return fmt.Errorf("Default effects must remain in shadow.")}
 if old:=m.current.Load();old!=nil{
  for _,before:=range old.cfg.Sources{for _,after:=range c.Sources{if before.Name!=after.Name{continue}
   // A renamed source starts a new cursor. Reusing an old cursor against a
   // different transport or item mapping can silently skip unrelated data.
   a,b:=before,after;a.Every=0;b.Every=0;a.Paused=false;b.Paused=false;a.Priority="";b.Priority="";a.Units=nil;b.Units=nil
   if !reflect.DeepEqual(a,b){return fmt.Errorf("A source identity or mapping changed. Use a new source name and explicitly accept a new cursor.")}
  }}
 }
 disk,err:=os.ReadFile(m.path);if err!=nil&&!os.IsNotExist(err){return fmt.Errorf("Cannot inspect config file.")};if revision(string(disk))!=base{return fmt.Errorf("Configuration was changed outside the UI. Restart with the external file or restore the active version before applying.")}
 // Retain checkpoints for existing names; remove only fresh preparation
 // checkpoints if activation fails before the revision becomes active.
 fresh:=[]string{};for _,s:=range c.Sources{cursor,e:=m.db.Cursor(s.Name);if e!=nil{return fmt.Errorf("Cannot read source checkpoint.")};if cursor==""{fresh=append(fresh,s.Name)}}
 activated:=false
 defer func(){if !activated{for _,name:=range fresh{m.db.Exec(`DELETE FROM source_cursors WHERE name=?`,name)}}}()
 jobs,err:=m.prepare(c);if err!=nil{return err}
 if ctx.Err()!=nil{return fmt.Errorf("Activation request canceled before changes.")}
 old:=m.current.Load()
 if m.stopSources!=nil{close(m.stopSources);m.sources.Wait()}
 // After draining, old runners can be restarted without preparing or resetting
 // their checkpoints if a file conflict or storage failure prevents activation.
 resume:=func(){if old!=nil{if oldJobs,e:=m.prepare(old.cfg);e==nil{m.startSources(oldJobs,old.rt)}}}
 disk,err=os.ReadFile(m.path);if (err!=nil&&!os.IsNotExist(err))||revision(string(disk))!=base{resume();return fmt.Errorf("Configuration changed while sources drained. No revision was activated.")}
 if ctx.Err()!=nil{resume();return fmt.Errorf("Activation canceled; previous configuration retained.")}
 id:=revision(text)
 if err=m.audit("activate",id,"intent");err!=nil{resume();return fmt.Errorf("Cannot audit activation; previous configuration retained.")}
 if _,err=m.db.Exec(`INSERT INTO control_revisions(id,yaml,created_at,status,base) VALUES(?,?,?,'prepared',?) ON CONFLICT(id) DO UPDATE SET status='prepared'`,id,text,time.Now().UTC().Format(time.RFC3339Nano),base);err!=nil{resume();return fmt.Errorf("Cannot store revision.")}
 if err=replaceConfig(m.path,text);err!=nil{resume();return fmt.Errorf("Configuration file update failed. Check disk state before retrying.")}
 snap:=m.snapshot(c,text);m.current.Store(snap);activated=true;m.startSources(jobs,snap.rt)
 // The file is startup authority. A crash after its rename is reconciled from
 // that file on boot; audit may retain intent rather than invent completion.
 if _,err=m.db.Exec(`UPDATE control_revisions SET status='active' WHERE id=?`,id);err!=nil{return fmt.Errorf("Configuration is active, but history update failed. Reload status before retrying.")}
 if err=m.audit("activate",id,"active");err!=nil{return fmt.Errorf("Configuration is active, but completion audit failed.")}
 return nil
}

