func TestReturnToShadowSuppressesInFlightEffect(t *testing.T){
 started,release:=make(chan struct{}),make(chan struct{})
 modelServer:=httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){
  close(started)
  select{case <-release:case <-r.Context().Done():return}
  json.NewEncoder(w).Encode(map[string]any{"choices":[]any{map[string]any{"message":map[string]any{"content":`{"category":"important","importance":1}`}}}})
 }));defer modelServer.Close()
 var calls atomic.Int32
 adapter:=httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){calls.Add(1)}));defer adapter.Close()
 rt:=newTestRuntime(t,modelServer.URL)
 rt.Policy.Rules[0].Then=policy.Then{Action:&policy.Action{Type:"http",URL:adapter.URL,Method:"POST"}}
 rt.ConfigRevision="test-revision"
 var blocked atomic.Bool;rt.EffectsBlocked=blocked.Load
 e:=testEvent("");done:=make(chan error,1)
 ctx,cancel:=context.WithTimeout(context.Background(),5*time.Second);defer cancel()
 go func(){_,err:=rt.Ingest(ctx,e);done<-err}()
 select{case <-started:case <-ctx.Done():t.Fatal("model did not start")}
 blocked.Store(true);close(release)
 if err:=<-done;err!=nil{t.Fatal(err)}
 if calls.Load()!=0{t.Fatal("effect dispatched after operator safety gate")}
 ins,err:=rt.DB.Inspect(e.ID);if err!=nil{t.Fatal(err)}
 if ins.ConfigRevision!="test-revision"||len(ins.Executions)!=1||ins.Executions[0].Status!="shadow"{t.Fatalf("missing safety evidence: %+v",ins)}
 found:=false;for _,step:=range ins.Trace{if step.Stage=="safety"{found=true}};if !found{t.Fatal("operator suppression missing from trace")}
}

'use strict';

// Optional real-browser regression suite. It uses Chrome's debugging protocol
// and Node's built-in WebSocket, so production needs no frontend dependencies.
const assert = require('node:assert/strict');
const fs = require('node:fs/promises');
const os = require('node:os');
const path = require('node:path');
const {spawn} = require('node:child_process');
const {once} = require('node:events');
const delay = ms => new Promise(resolve => setTimeout(resolve, ms));
(async () => {
  const profile = await fs.mkdtemp(path.join(os.tmpdir(), 'mrmr-browser-'));
  const chrome = spawn(process.env.MRMR_CHROME, ['--headless', '--disable-gpu', '--no-first-run', '--remote-debugging-port=0', `--user-data-dir=${profile}`, 'about:blank'], {stdio:'ignore'});
  let socket;
  try {
    let port;
    for (let i=0;i<100;i++) { try { port=(await fs.readFile(path.join(profile,'DevToolsActivePort'),'utf8')).split('\n')[0]; break; } catch { await delay(50); } }
    assert.ok(port,'Chrome debugging endpoint did not start');
    const pages=await (await fetch(`http://127.0.0.1:${port}/json/list`)).json();
    socket=new WebSocket(pages[0].webSocketDebuggerUrl);
    await new Promise((resolve,reject)=>{socket.onopen=resolve;socket.onerror=reject;});
    let sequence=0;const waiting=new Map(),errors=[];
    socket.onmessage=event=>{const msg=JSON.parse(event.data);if(msg.id){const job=waiting.get(msg.id);waiting.delete(msg.id);if(msg.error)job.reject(Error(msg.error.message));else job.resolve(msg.result);}else if(msg.method==='Runtime.exceptionThrown'){errors.push(msg.params.exceptionDetails.text);}};
    const rpc=(method,params={})=>new Promise((resolve,reject)=>{const id=++sequence;waiting.set(id,{resolve,reject});socket.send(JSON.stringify({id,method,params}));});
    const evaluate=async expression=>{const result=await rpc('Runtime.evaluate',{expression,awaitPromise:true,returnByValue:true});if(result.exceptionDetails)throw Error(result.exceptionDetails.exception?.description||result.exceptionDetails.text);return result.result.value;};
    const until=async expression=>{for(let i=0;i<100;i++){if(await evaluate(expression))return;await delay(50);}throw Error(`Timed out: ${expression}`);};
    await rpc('Runtime.enable');await rpc('Page.enable');
    await rpc('Page.navigate',{url:process.env.MRMR_BROWSER_URL+'/manage/'});
    await until("!!document.getElementById('login-form')");
    await evaluate(`document.getElementById('token').value=${JSON.stringify(process.env.MRMR_BROWSER_TOKEN)};document.getElementById('login-form').requestSubmit()`);
    await until("!document.getElementById('app').hidden");
    for(const width of [390,1440]){
      await rpc('Emulation.setDeviceMetricsOverride',{width,height:1000,deviceScaleFactor:1,mobile:width<600});
      for(const section of ['overview','configure','activity','review','runtime']){
        await evaluate(`location.hash=${JSON.stringify(section)}`);await delay(80);
        const sizes=await evaluate('({scroll:document.documentElement.scrollWidth,width:innerWidth})');
        assert.ok(sizes.scroll<=sizes.width+1,`${section} overflows at ${width}: ${JSON.stringify(sizes)}`);
        if(process.env.MRMR_BROWSER_ARTIFACTS){await fs.mkdir(process.env.MRMR_BROWSER_ARTIFACTS,{recursive:true});const shot=await rpc('Page.captureScreenshot',{format:'png',captureBeyondViewport:false});await fs.writeFile(path.join(process.env.MRMR_BROWSER_ARTIFACTS,`manage-${section}-${width}.png`),Buffer.from(shot.data,'base64'));}
      }
    }
    await evaluate("location.hash='configure';document.getElementById('yaml').value=document.getElementById('yaml').value.replace('Classify this event.','A browser-tested contract.');document.getElementById('yaml').dispatchEvent(new Event('input'));document.getElementById('save-draft').click()");
    await until("document.getElementById('notice').textContent.includes('Draft saved')");
    await evaluate("document.getElementById('show-diff').click()");
    assert.ok(await evaluate("document.getElementById('diff-content').textContent.includes('A browser-tested contract.')"));
    await evaluate("document.getElementById('apply-confirm').checked=true;document.getElementById('activate').click()");
    await until("document.getElementById('notice').textContent.includes('configuration is active')");
    await evaluate("location.hash='activity'");
    await until("!!document.querySelector('#events a')");
    await evaluate("document.querySelector('#events a').click()");
    await until("!document.getElementById('event-detail').hidden");
    assert.ok(await evaluate("document.getElementById('event-detail').textContent.includes('9007199254740993')"));
    assert.equal(await evaluate('window.mrmrInjected'),undefined);
    await evaluate("document.querySelector('#event-detail button').click()");
    await until("!document.getElementById('review-form').hidden");
    assert.equal(await evaluate("document.getElementById('category').value"),'');
    await evaluate("document.getElementById('review-origin').value='synthetic';document.getElementById('category').value='routine';document.getElementById('requires-action').value='false';document.getElementById('expected-outcome').value='ignore';document.getElementById('review-form').requestSubmit()");
    await until("document.getElementById('notice').textContent.includes('Review saved')");
    // Lock must remove private content, not merely hide the navigation.
    await evaluate("document.getElementById('logout').click()");
    assert.equal(await evaluate("document.getElementById('yaml').value"),'');
    assert.equal(await evaluate("document.getElementById('event-detail').textContent"),'');
    assert.deepEqual(errors,[]);
    console.log('Management browser journeys passed at phone and desktop widths.');
  } finally {
    if(socket)socket.close();
    const exit=once(chrome,'exit');chrome.kill('SIGTERM');await Promise.race([exit,delay(2000).then(()=>chrome.kill('SIGKILL'))]);
    await fs.rm(profile,{recursive:true,force:true});
  }
})().catch(err=>{console.error(err.message);process.exitCode=1;});

