edits.newText:
errs := make(chan error, len(servers))
var serving, requests sync.WaitGroup
var admission sync.Mutex
accepting := true
for i, s := range servers {
	handler := s.Handler
	s.BaseContext = func(net.Listener) context.Context { return ctx }
	s.Handler = http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		admission.Lock()
		if !accepting { admission.Unlock(); http.Error(w,"Runtime is stopping.",503); return }
		requests.Add(1)
		admission.Unlock()
		defer requests.Done()
		handler.ServeHTTP(w,r)
	})
	serving.Add(1)
	go func() { defer serving.Done(); errs <- s.Serve(listeners[i]) }()
}
defer func() {
	// Serve returning does not mean its handlers have returned. Close
	// admission, cancel connections, and join handlers before closing SQLite.
	admission.Lock(); accepting=false; admission.Unlock()
	for _, s := range servers { s.Close() }
	serving.Wait()
	requests.Wait()
}()

