package main

import (
 "bytes"
 "context"
 "io"
 "net"
 "net/http"
 "net/http/httptest"
 "os"
 "os/exec"
 "path/filepath"
 "runtime"
 "strconv"
 "strings"
 "testing"
 "time"

 "github.com/heath0xff/mrmr/internal/storage"
)

// The helper is a real process so signal cancellation and HTTP handler ownership
// are exercised without sending process-wide signals to the test runner itself.
func TestManagedProcessHelper(t *testing.T){
 if os.Getenv("MRMR_TEST_MANAGED_CHILD")!="1"{t.Skip("subprocess helper")}
 if err:=runManaged(os.Getenv("MRMR_TEST_CONFIG"),os.Getenv("MRMR_TEST_ADDR"),"","MRMR_TEST_CONTROL_TOKEN",false,"");err!=nil{t.Fatal(err)}
}
func TestManagedProcessDrainsHTTPBeforeClosingStorage(t *testing.T){
 if runtime.GOOS=="windows"{t.Skip("interrupt-based lifecycle test")}
 modelStarted,release:=make(chan struct{}),make(chan struct{})
 model:=httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){io.Copy(io.Discard,r.Body);close(modelStarted);select{case <-r.Context().Done():case <-release:}}))
 defer model.Close();defer close(release)
 freeAddress:=func()string{l,err:=net.Listen("tcp","127.0.0.1:0");if err!=nil{t.Fatal(err)};addr:=l.Addr().String();l.Close();return addr}
 controlAddr,ingressAddr:=freeAddress(),freeAddress()
 dir:=t.TempDir();configPath,dbPath:=filepath.Join(dir,"mrmr.yaml"),filepath.Join(dir,"mrmr.db")
 text:=strings.ReplaceAll(controlYAML,"127.0.0.1:4242",ingressAddr)
 text=strings.ReplaceAll(text,"path: test.db","path: "+strconv.Quote(dbPath))
 text=strings.ReplaceAll(text,"http://127.0.0.1:1/v1",model.URL)
 if err:=os.WriteFile(configPath,[]byte(text),0600);err!=nil{t.Fatal(err)}
 child:=exec.Command(os.Args[0],"-test.run=^TestManagedProcessHelper$","-test.timeout=20s")
 child.Env=append(os.Environ(),"MRMR_TEST_MANAGED_CHILD=1","MRMR_TEST_CONFIG="+configPath,"MRMR_TEST_ADDR="+controlAddr,"MRMR_TEST_CONTROL_TOKEN=REDACTED
 var output bytes.Buffer;child.Stdout=&output;child.Stderr=&output
 if err:=child.Start();err!=nil{t.Fatal(err)}
 exited:=make(chan struct{});var childErr error
 go func(){childErr=child.Wait();close(exited)}()
 defer func(){select{case <-exited:default:child.Process.Kill();<-exited}}()
